// 이미 일어난 사실. 과거형, 바뀌지 않는다(불변)
{ type: 'ItemAdded',   id, text, by, at }   // 항목이 추가됨
{ type: 'ItemRenamed', id, text, by, at }   // 이름이 바뀜
{ type: 'ItemChecked', id, by, at }         // 완료됨
{ type: 'ItemRemoved', id, by, at }         // 지워짐

// 명령(AddItem, "해라") ≠ 이벤트(ItemAdded, "됐다")
// 자기 완결적. 그 이벤트만 보고 재생 가능(외부 상태 의존 X)
// 형식 진화 대비. 버전 필드 / 하위 호환(옛 이벤트도 읽혀야)

// 이벤트 목록을 접어(fold) 현재 상태를 만든다. reduce 와 같다
function project(events) {
  const items = new Map();
  for (const e of events) {
    if (e.type === 'ItemAdded')   items.set(e.id, { text: e.text, done: false });
    if (e.type === 'ItemRenamed') items.get(e.id).text = e.text;
    if (e.type === 'ItemChecked') items.get(e.id).done = true;
    if (e.type === 'ItemRemoved') items.delete(e.id);
  }
  return items;
}
// 상태 = 이벤트의 순수 함수. 같은 이벤트 목록 → 항상 같은 상태(재현 가능)
// 처음부터 N개만 접으면 → 그 시점의 상태(임의 시점 복원, 4장)
